 * Creates an ethereal, 56k modem-style loading text effect
 */
import { gsap } from 'gsap';

// Get random value between min and max
const getRandomValue = (min, max) => {
  return min + Math.random() * (max - min);
};

// Get random boolean based on probability
const getRandomBool = probability => {
  return Math.random() < probability;
};

/**
 * Split text into spans for animation
 * @param {HTMLElement} element - Element containing text to split
 * @returns {HTMLSpanElement[]} Array of span elements
 */
const splitTextIntoSpans = element => {
  if (!element || !element.textContent) return [];

  // Save original text and create a wrapper
  const text = element.textContent;
  const wrapper = document.createElement('span');
  wrapper.classList.add('gsap-text-wrapper');
  wrapper.style.display = 'inline-block';

  // Create spans for each character
  const spans = [];
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const span = document.createElement('span');
    span.textContent = char;
    span.style.display = 'inline-block';
    span.style.opacity = '0';
    span.classList.add('gsap-char');

    // Add special classes to some characters
    if (getRandomBool(0.08)) {
      span.classList.add('gsap-char-flicker');
    }
    if (getRandomBool(0.05)) {
      span.classList.add('gsap-char-glow');
    }
    wrapper.appendChild(span);
    spans.push(span);
  }

  // Replace element content with our spans
  element.textContent = '';
  element.appendChild(wrapper);
  return spans;
};

/**
