    stagger: {
      amount: getRandomValue(settings.staggerRange[0] * spans.length, settings.staggerRange[1] * spans.length),
      from: "start"
    },
    filter: "blur(0px)"
  }, 0);

  // Add blur effect for ethereal appearance
  timeline.fromTo(spans, {
    filter: "blur(3px)",
    y: 3
